 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='history: stage absent';END IF;
 PERFORM sessions.ingest_require_buffer_admission(v_org);PERFORM sessions.ingest_lock_fences(v_org,v_ws,v_user);
