   row_number()OVER(ORDER BY r.org_id COLLATE"C",r.workspace_id COLLATE"C",r.harness COLLATE"C",r.session_id COLLATE"C",r.machine_id COLLATE"C")-1,r.pointer,r.pointer_sha256
